const LOGO_BASE64_PEMINJAMAN = "";

/************************************************
 * SURAT JALAN PEMINJAMAN (PDF)
 * Diakses lewat Web App: .../exec?print=PJM-000012
 * 1 No Peminjaman = 1 PDF.
 ************************************************/

/************************************************
 * AMBIL DATA 1 PEMINJAMAN DARI SHEET "Peminjaman"
 ************************************************/
function ambilDataPeminjaman(noPeminjaman) {
  const ss = SpreadsheetApp.openById(SPREADSHEET_ID);
  const sheet = ss.getSheetByName(SHEET_PEMINJAMAN);
  if (!sheet) return null;

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return null;

  // A:N (No,Timestamp,Nama,Keperluan,TglPinjam,TglKembali,Produk,SKU,Size,Qty,NoPeminjaman,Status,Email,Lokasi)
  const values = sheet.getRange(2, 1, lastRow - 1, 14).getValues();

  const items = [];
  let namaPeminjam = "";
  let keperluan = "";
  let tglPinjam = null;
  let tglKembali = null;
  let timestamp = null;

  values.forEach(function (row) {
    const noPjmRow = String(row[10] || "").trim(); // K
    if (noPjmRow !== noPeminjaman) return;

    items.push({
      produk: String(row[6] || "").trim(),  // G
      sku: String(row[7] || "").trim(),     // H
      size: String(row[8] || "").trim(),    // I
      qty: Number(row[9]) || 0,             // J
      lokasi: String(row[13] || "").trim()  // N
    });

    if (!timestamp) timestamp = row[1];             // B
    if (!namaPeminjam) namaPeminjam = String(row[2] || "").trim(); // C
    if (!keperluan) keperluan = String(row[3] || "").trim();       // D
    if (!tglPinjam) tglPinjam = row[4];              // E
    if (!tglKembali) tglKembali = row[5];            // F
  });

  if (items.length === 0) return null;

  return {
    noPeminjaman: noPeminjaman,
    timestamp: timestamp,
    namaPeminjam: namaPeminjam,
    keperluan: keperluan,
    tglPinjam: tglPinjam,
    tglKembali: tglKembali,
    items: items
  };
}

/************************************************
 * FORMAT TANGGAL AMAN
 * (tglPinjam/tglKembali bisa berupa Date object atau
 * string "yyyy-mm-dd" dari input type=date di form)
 ************************************************/
function formatTanggalAman(value) {
  if (!value) return "-";
  try {
    const d = (value instanceof Date) ? value : new Date(value);
    if (isNaN(d.getTime())) return String(value);
    return Utilities.formatDate(d, "Asia/Jakarta", "dd MMMM yyyy");
  } catch (e) {
    return String(value);
  }
}

/************************************************
 * BANGUN HTML SURAT JALAN PEMINJAMAN
 ************************************************/
function buildSuratJalanPeminjamanHtml(data) {
  const tglSubmit = formatTanggalAman(data.timestamp);
  const tglPinjamStr = formatTanggalAman(data.tglPinjam);

  // Isi QR: perintah command style, sesuai konvensi #OUT yang sudah ada di sistem
  const isiQr = '#OUT "Peminjaman Invoice ' + data.noPeminjaman + '"';
  const qrUrl = "https://api.qrserver.com/v1/create-qr-code/?size=90x90&data=" + encodeURIComponent(isiQr);

  let rowsHtml = "";
  data.items.forEach(function (it, i) {
    rowsHtml += `<tr>
      <td style="text-align:center;">${i + 1}</td>
      <td>${it.produk}</td>
      <td style="text-align:center;">${it.size}</td>
      <td>${it.sku}</td>
      <td style="text-align:center;">${it.qty}</td>
      <td>${it.lokasi}</td>
    </tr>`;
  });

  return `<html><head><style>
    @page { size: A4; margin: 15mm; }
    body { font-family: Arial, sans-serif; color:#3A2A28; }
    .header { display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid #B5697A; padding-bottom:14px; margin-bottom:18px; }
    .header img.logo { height:56px; }
    .header .judul { text-align:right; }
    .header .judul h1 { margin:0; font-size:20px; color:#7A3E42; }
    .header .judul p { margin:2px 0 0; font-size:11px; color:#9C8481; }
    .info-table { width:100%; margin-bottom:18px; border-collapse:collapse; }
    .info-table td { padding:4px 0; font-size:13px; vertical-align:top; }
    .info-table td.label { width:150px; color:#9C8481; }
    table.items { width:100%; border-collapse:collapse; margin-bottom:30px; }
    table.items th { background:#FBF3EF; border:1px solid #ecdcd8; padding:7px; font-size:12px; text-align:left; }
    table.items td { border:1px solid #ecdcd8; padding:7px; font-size:12.5px; }
  </style></head><body>

    <div class="header">
      <img class="logo" src="data:image/png;base64,${LOGO_BASE64_PEMINJAMAN}" alt="Chocochips">
      <div class="judul">
        <h1>SURAT PEMINJAMAN SEMENTARA</h1>
        <p>Peminjaman Sementara Barang</p>
      </div>
      <img src="${qrUrl}" width="90" height="90" alt="QR" style="width:90px; height:90px; flex-shrink:0; display:block;">
    </div>

    <table class="info-table">
      <tr><td class="label">No Peminjaman</td><td><b>${data.noPeminjaman}</b></td></tr>
      <tr><td class="label">Tanggal Pengajuan</td><td>${tglSubmit}</td></tr>
      <tr><td class="label">Nama / PIC Peminjam</td><td>${data.namaPeminjam}</td></tr>
      <tr><td class="label">Keperluan</td><td>${data.keperluan}</td></tr>
      <tr><td class="label">Tanggal Peminjaman</td><td>${tglPinjamStr}</td></tr>
    </table>

    <table class="items">
      <thead>
        <tr>
          <th style="width:30px;">No</th>
          <th>Nama Produk</th>
          <th style="width:60px;">Size</th>
          <th style="width:110px;">SKU</th>
          <th style="width:50px;">Qty</th>
          <th style="width:100px;">Lokasi</th>
        </tr>
      </thead>
      <tbody>
        ${rowsHtml}
      </tbody>
    </table>

  </body></html>`;
}

/************************************************
 * GENERATE PDF BLOB
 ************************************************/
function generateSuratJalanPeminjamanPdf(noPeminjaman) {
  const data = ambilDataPeminjaman(noPeminjaman);
  if (!data) return null;

  const html = buildSuratJalanPeminjamanHtml(data);
  return Utilities.newBlob(html, "text/html", "surat-jalan-peminjaman.html").getAs("application/pdf");
}

/************************************************
 * CETAK VIA MENU SPREADSHEET
 * TIDAK bikin onOpen() sendiri di sini -- project ini
 * SUDAH punya onOpen() di file lain (yang bikin menu
 * "PDF Printing"). Tinggal tambahkan 1 baris manual
 * di onOpen() yang sudah ada:
 *
 *   .addItem('Cetak Surat Jalan Peminjaman', 'cetakSuratJalanPeminjamanViaMenu')
 *
 * supaya nggak ada 2 fungsi onOpen() yang saling
 * menimpa (bentrok) seperti kejadian rebuildStock()
 * sebelumnya.
 ************************************************/
function cetakSuratJalanPeminjamanViaMenu() {
  const ui = SpreadsheetApp.getUi();

  const resp = ui.prompt(
    "Cetak Surat Jalan Peminjaman",
    "Masukkan No Peminjaman (contoh: PJM-000012):",
    ui.ButtonSet.OK_CANCEL
  );

  if (resp.getSelectedButton() !== ui.Button.OK) return;

  const noPeminjaman = resp.getResponseText().trim();
  if (!noPeminjaman) {
    ui.alert("No Peminjaman tidak boleh kosong.");
    return;
  }

  const blob = generateSuratJalanPeminjamanPdf(noPeminjaman);
  if (!blob) {
    ui.alert('Data untuk No Peminjaman "' + noPeminjaman + '" tidak ditemukan.');
    return;
  }

  const base64 = Utilities.base64Encode(blob.getBytes());
  const dataUri = "data:application/pdf;base64," + base64;

  const html = HtmlService.createHtmlOutput(
    "<script>" +
    "var win = window.open();" +
    "win.document.write(\"<iframe src='" + dataUri + "' style='width:100%; height:100%; border:none;'></iframe>\");" +
    "setTimeout(function(){ win.print(); google.script.host.close(); }, 1500);" +
    "</script>"
  ).setWidth(300).setHeight(50);

  ui.showModalDialog(html, "Membuka PDF...");
}